// One of the two packages of the WP21 S1 fixture. Both keep a private
// `helper`, both export a `scale`, and the program that uses them keeps a
// private `helper` of its own; before package-scoped symbols the three names
// were one flat namespace and this could not be compiled at all.

const helper = (n: i32): i32 => n + 1;

export const scale = (n: i32): i32 => helper(n) * 2;
